using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;using System.Security.Cryptography;using System.Text;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
// EditorJsonUtility emits legacy integer instanceID values; resolve only those references.
#pragma warning disable CS0618
public static class ENApply {
 static readonly Dictionary<int,string> refs=new Dictionary<int,string>();
 static string Stable(int id){if(id==0)return "null";if(refs.TryGetValue(id,out var r))return r;var o=EditorUtility.InstanceIDToObject(id);return refs[id]=o?GlobalObjectId.GetGlobalObjectIdSlow(o).ToString():"missing:"+id;}
 static void Normalize(JToken t){if(t is JObject o){if(o.Count==1&&o["instanceID"]!=null){o["instanceID"]=Stable((int)o["instanceID"]);return;}foreach(var p in o.Properties().ToArray())Normalize(p.Value);}else if(t is JArray a)foreach(var v in a)Normalize(v);}
 static string Hash(UnityEngine.Object obj,string originalName=null){var json=JObject.Parse(EditorJsonUtility.ToJson(obj));if(obj is GameObject&&originalName!=null)json["GameObject"]["m_Name"]=originalName;Normalize(json);using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(json.ToString(Formatting.None)))).Replace("-","");}
 static SortedDictionary<string,string> Snapshot(Scene s,Dictionary<string,string> oldNames=null){refs.Clear();var d=new SortedDictionary<string,string>();foreach(var t in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true))){string id=GlobalObjectId.GetGlobalObjectIdSlow(t.gameObject).ToString(),old=null;if(oldNames!=null)oldNames.TryGetValue(id,out old);d[id]=Hash(t.gameObject,old);int missing=0;foreach(var c in t.GetComponents<Component>()){if(!c){missing++;continue;}d[GlobalObjectId.GetGlobalObjectIdSlow(c).ToString()]=Hash(c);}if(missing>0)d[GlobalObjectId.GetGlobalObjectIdSlow(t).ToString()+"_missingScripts"]=missing.ToString();}return d;}
 static void CheckBindings(Scene s,HashSet<Transform> rename){foreach(var animator in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Animator>(true))){if(!animator.runtimeAnimatorController)continue;foreach(var clip in animator.runtimeAnimatorController.animationClips.Distinct())foreach(var b in AnimationUtility.GetCurveBindings(clip).Concat(AnimationUtility.GetObjectReferenceCurveBindings(clip))){var t=animator.transform.Find(b.path);if(!t)continue;for(var p=t;p&&p!=animator.transform;p=p.parent)if(rename.Contains(p))throw new Exception("Animation binding requires migration: "+clip.name+" "+b.path);}}}
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit mode required");string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../..")),h=repo+"/SourceAssets/EnglishNaming/";var plan=JArray.Parse(File.ReadAllText(h+"rename_plan.json"));var setup=EditorSceneManager.GetSceneManagerSetup();var results=new List<object>();
  try{foreach(var group in plan.GroupBy(x=>(string)x["scene"])){var s=EditorSceneManager.OpenScene(group.Key,OpenSceneMode.Single);string baseline=h+Path.GetFileNameWithoutExtension(group.Key)+"_properties_before.json";var before=File.Exists(baseline)?JsonConvert.DeserializeObject<SortedDictionary<string,string>>(File.ReadAllText(baseline)):Snapshot(s);var pairs=group.Select(q=>{GlobalObjectId.TryParse((string)q["id"],out var id);var t=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(id) as Transform;if(!t||(t.name!=(string)q["old"]&&t.name!=(string)q["new"]))throw new Exception("Stale rename plan "+q["old"]);return new{t,q};}).ToArray();CheckBindings(s,new HashSet<Transform>(pairs.Select(p=>p.t)));var oldNames=pairs.ToDictionary(p=>GlobalObjectId.GetGlobalObjectIdSlow(p.t.gameObject).ToString(),p=>(string)p.q["old"]);
   foreach(var p in pairs){p.t.name=(string)p.q["new"];if(PrefabUtility.IsPartOfPrefabInstance(p.t.gameObject))PrefabUtility.RecordPrefabInstancePropertyModifications(p.t.gameObject);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);s=EditorSceneManager.OpenScene(group.Key,OpenSceneMode.Single);var after=Snapshot(s,oldNames);var differences=before.Where(p=>!after.TryGetValue(p.Key,out var a)||a!=p.Value).Select(p=>p.Key).Concat(after.Keys.Except(before.Keys)).ToArray();int remaining=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Count(t=>Regex.IsMatch(t.name,"[\\u1100-\\u11ff\\u3130-\\u318f\\uac00-\\ud7af]"));
   File.WriteAllText(h+Path.GetFileNameWithoutExtension(group.Key)+"_properties_before.json",JsonConvert.SerializeObject(before,Formatting.Indented));File.WriteAllText(h+Path.GetFileNameWithoutExtension(group.Key)+"_properties_after.json",JsonConvert.SerializeObject(after,Formatting.Indented));results.Add(new{scene=group.Key,renamed=pairs.Length,comparedObjects=before.Count,nonNameChanges=differences,remainingKoreanNames=remaining});if(differences.Length>0||remaining>0)throw new Exception("Post-rename validation failed "+group.Key+" differences="+differences.Length+" Korean="+remaining);
  }}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);File.WriteAllText(h+"result.json",JsonConvert.SerializeObject(results,Formatting.Indented));}return results;}
}
